/**
 * Benchmark harness — the open, reproducible core of "is this getting better?".
 *
 * A case is a (mood, period) pair plus a deterministic seed. The CANDIDATE
 * palette is generated by code, never by a model, so the only variable in a run
 * is the REVIEWER's judgment. Every candidate is hashed into the result set, and
 * every run pins the goal, the prompt, the case-set version, and the reviewer
 * identity. Result sets are plain JSON: anyone can inspect, diff, re-run, or
 * cite them.
 *
 * Scope conformance — "nothing about anything other than the goal as committed"
 * — is a first-class metric. A rationale or tweak reason that strays off-goal is
 * flagged, not hidden.
 */

import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { deltaEOk, hexToOklch } from './color.js';
import { paths } from './config.js';
import { generatePalette } from './generate.js';
import { hashText } from './hash.js';
import { applyTweaks, type ReviewBackend, reviewPromptHash } from './review/index.js';
import { seedFromString } from './rng.js';
import type {
  Contrast,
  Energy,
  MoodInput,
  PaletteSuggestion,
  RawPalette,
  Warmth,
} from './types.js';

/** The committed goal. Bump with care — every run pins its hash. */
export const BENCH_GOAL =
  'Review a code-generated terminal palette for mood fit and readability, then either approve it or propose minimal slot tweaks. Nothing off-goal.';

export const CASE_SET_VERSION = 1;
export const SIZES = { quick: 12, standard: 45, full: 135 } as const;

const ENERGIES: Energy[] = ['low', 'med', 'high'];
const WARMTHS: Warmth[] = ['cool', 'neutral', 'warm'];
const CONTRASTS: Contrast[] = ['soft', 'balanced', 'vivid'];
const PERIODS = ['morning', 'lunch', 'afternoon', 'evening', 'owl'];

export interface BenchCase {
  id: string;
  mood: MoodInput;
  period: string;
}

export interface BenchCaseResult {
  caseId: string;
  candidateHash: string;
  validationOk: boolean;
  validationClean: boolean;
  approved: boolean;
  tweaks: number;
  meanTweakDeltaE: number;
  rationale: string;
  /** true when the reviewer's text strayed off the committed goal */
  scopeViolation: boolean;
  latencyMs: number;
}

export interface BenchSummary {
  cases: number;
  approvedRate: number;
  meanTweaks: number;
  meanTweakDeltaE: number;
  validRate: number;
  cleanRate: number;
  scopeViolations: number;
  meanLatencyMs: number;
  totalLatencyMs: number;
}

export interface BenchRun {
  schema: 1;
  name: string;
  company?: string;
  model: string;
  pluginId: string;
  pluginVersion: string;
  promptHash: string;
  goalHash: string;
  caseSet: number;
  runSeed: string;
  startedAt: string;
  summary: BenchSummary;
  cases: BenchCaseResult[];
}

/** Deterministic case ladder: period-major, then mood. Same order, always. */
export function buildCases(size: number = SIZES.quick): BenchCase[] {
  const cases: BenchCase[] = [];
  for (const period of PERIODS)
    for (const energy of ENERGIES)
      for (const warmth of WARMTHS)
        for (const contrast of CONTRASTS) {
          cases.push({
            id: `${period}-${energy}-${warmth}-${contrast}`,
            mood: { energy, warmth, contrast },
            period,
          });
          if (cases.length >= size) return cases;
        }
  return cases;
}

const OFF_SCOPE: RegExp[] = [
  /https?:\/\/|www\./i,
  /[\w.+-]+@[\w-]+\.[\w.]+/,
  /```/,
  /\b(ignore (all|previous)|system prompt|jailbreak|as an ai)\b/i,
];
const ON_SCOPE =
  /\b(color|colou?r|palette|contrast|hue|lightness|chroma|saturat|mood|scheme|slot|foreground|background|cursor|tone|readab|legib|vibrant|muted|warm|cool|ansi|dark|light)\b/i;

/**
 * Heuristic scope-conformance check. Flags off-goal material: links, addresses,
 * prompt-injection phrasing, or a substantive rationale with no palette-related
 * vocabulary at all. Deliberately conservative and documented as heuristic.
 */
export function scopeCheck(text: string): boolean {
  const t = text.trim();
  if (!t) return false;
  if (OFF_SCOPE.some((re) => re.test(t))) return true;
  return t.length > 40 && !ON_SCOPE.test(t);
}

function slotHex(palette: RawPalette, scheme: 'light' | 'dark', slot: string): string | null {
  const s = scheme === 'light' ? palette.light : palette.dark;
  if (slot === 'foreground') return s.foreground;
  if (slot === 'background') return s.background;
  if (slot === 'cursor') return s.cursor;
  const m = /^color(\d+)$/.exec(slot);
  if (!m) return null;
  return s.colors[Number(m[1])] ?? null;
}

export function summarize(results: BenchCaseResult[]): BenchSummary {
  const n = results.length || 1;
  const totalTweaks = results.reduce((a, r) => a + r.tweaks, 0);
  const weightedDelta = results.reduce((a, r) => a + r.meanTweakDeltaE * r.tweaks, 0);
  const totalLatency = results.reduce((a, r) => a + r.latencyMs, 0);
  return {
    cases: results.length,
    approvedRate: results.filter((r) => r.approved).length / n,
    meanTweaks: totalTweaks / n,
    meanTweakDeltaE: totalTweaks ? weightedDelta / totalTweaks : 0,
    validRate: results.filter((r) => r.validationOk).length / n,
    cleanRate: results.filter((r) => r.validationClean).length / n,
    scopeViolations: results.filter((r) => r.scopeViolation).length,
    meanLatencyMs: totalLatency / n,
    totalLatencyMs: totalLatency,
  };
}

function randomRunSeed(): string {
  const bytes = crypto.getRandomValues(new Uint8Array(8));
  return [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');
}

export interface BenchOptions {
  label: string;
  company?: string;
  model?: string;
  reviewer: ReviewBackend;
  size?: number;
  runSeed?: string;
  onCase?: (done: number, total: number) => void;
}

export async function runBench(opts: BenchOptions): Promise<BenchRun> {
  const runSeed = opts.runSeed ?? randomRunSeed();
  const cases = buildCases(opts.size ?? SIZES.quick);
  const results: BenchCaseResult[] = [];

  for (const c of cases) {
    const seed = seedFromString(`${runSeed}:${c.id}`);
    const { palette } = await generatePalette(c.mood, { period: c.period, seed });

    const started = Date.now();
    let suggestion: PaletteSuggestion;
    try {
      suggestion = await opts.reviewer.review(palette, c.mood);
    } catch (err) {
      suggestion = {
        approved: true,
        rationale: `reviewer error: ${(err as Error).message}`,
        tweaks: [],
      };
    }
    const latencyMs = Date.now() - started;

    const deltas = suggestion.tweaks
      .map((t) => {
        const before = slotHex(palette, t.scheme, t.slot);
        return before ? deltaEOk(hexToOklch(before), hexToOklch(t.hex)) : null;
      })
      .filter((d): d is number => d !== null);
    const meanTweakDeltaE = deltas.length ? deltas.reduce((a, b) => a + b, 0) / deltas.length : 0;

    const scopeViolation =
      scopeCheck(suggestion.rationale) || suggestion.tweaks.some((t) => scopeCheck(t.reason));

    // A rejected tweak (one that would break validation) is not applied; the
    // final validation reflects what a reviewer could actually ship.
    const applied = applyTweaks(palette, suggestion.tweaks).validation;

    results.push({
      caseId: c.id,
      candidateHash: hashText(JSON.stringify(palette)),
      validationOk: applied.ok,
      validationClean: applied.clean,
      approved: suggestion.approved,
      tweaks: suggestion.tweaks.length,
      meanTweakDeltaE,
      rationale: suggestion.rationale,
      scopeViolation,
      latencyMs,
    });
    opts.onCase?.(results.length, cases.length);
  }

  return {
    schema: 1,
    name: opts.label,
    company: opts.company,
    model: opts.model ?? opts.label,
    pluginId: `review:${opts.reviewer.mode}`,
    pluginVersion: '1',
    promptHash: reviewPromptHash(),
    goalHash: hashText(BENCH_GOAL),
    caseSet: CASE_SET_VERSION,
    runSeed,
    startedAt: new Date().toISOString(),
    summary: summarize(results),
    cases: results,
  };
}

// --- bookmarks: named, attributable result sets -----------------------------

function runsDir(): string {
  return join(paths().base, 'runs');
}

export function slug(name: string): string {
  return (
    name
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '') || 'run'
  );
}

/** Persist a run as a named bookmark; returns the file path. */
export function saveRun(run: BenchRun): string {
  mkdirSync(runsDir(), { recursive: true });
  const file = join(runsDir(), `${slug(run.name)}.json`);
  writeFileSync(file, `${JSON.stringify(run, null, 2)}\n`, 'utf8');
  return file;
}

export function listRuns(): BenchRun[] {
  if (!existsSync(runsDir())) return [];
  return readdirSync(runsDir())
    .filter((f) => f.endsWith('.json'))
    .map((f) => {
      try {
        return JSON.parse(readFileSync(join(runsDir(), f), 'utf8')) as BenchRun;
      } catch {
        return null;
      }
    })
    .filter((r): r is BenchRun => r !== null)
    .sort((a, b) => b.startedAt.localeCompare(a.startedAt));
}

export function loadRun(name: string): BenchRun | null {
  const file = join(runsDir(), `${slug(name)}.json`);
  if (!existsSync(file)) return null;
  try {
    return JSON.parse(readFileSync(file, 'utf8')) as BenchRun;
  } catch {
    return null;
  }
}

/** Human-readable comparison of two bookmarked runs. */
export function compareRuns(a: BenchRun, b: BenchRun): string {
  const rows: Array<[string, string]> = [
    ['model', `${a.model}  vs  ${b.model}`],
    ['cases', `${a.summary.cases}  vs  ${b.summary.cases}`],
    [
      'approved',
      `${(a.summary.approvedRate * 100).toFixed(1)}%  vs  ${(b.summary.approvedRate * 100).toFixed(1)}%`,
    ],
    ['mean tweaks', `${a.summary.meanTweaks.toFixed(2)}  vs  ${b.summary.meanTweaks.toFixed(2)}`],
    [
      'mean tweak ΔE',
      `${a.summary.meanTweakDeltaE.toFixed(4)}  vs  ${b.summary.meanTweakDeltaE.toFixed(4)}`,
    ],
    ['scope violations', `${a.summary.scopeViolations}  vs  ${b.summary.scopeViolations}`],
    [
      'mean latency',
      `${a.summary.meanLatencyMs.toFixed(0)}ms  vs  ${b.summary.meanLatencyMs.toFixed(0)}ms`,
    ],
    ['prompt hash', `${a.promptHash.slice(0, 12)}  vs  ${b.promptHash.slice(0, 12)}`],
    ['goal hash', `${a.goalHash.slice(0, 12)}  vs  ${b.goalHash.slice(0, 12)}`],
  ];
  return rows.map(([k, v]) => `${k.padEnd(16)} ${v}`).join('\n');
}
